// 「作者模型」：与 demo-mock-model.mjs 同协议的本地 OpenAI 兼容服务，
// 但所有返回内容是主笔为《泊星港：禁航之海的少年船长》亲手创作的正稿。
// 软件正常调用生成 → 作者在界面逐项审核接受，全部正史门禁照常生效。
// 仅限本项目创作使用，不属于产品代码，不随发布。
import { createServer } from "node:http";

const PROSE_FALLBACK =
  "云在船底翻涌，像一锅烧开的牛奶。岑野舟趴在白鲸号的桅斗里，数着星骸带里浮沉的碎光。" +
  "每一粒都是一颗死掉的星星，而海图上说，它们都记得回家的路。";

function phaseOf(prompt) {
  if (prompt.includes("小说文风分析师")) return "style";
  if (prompt.includes("开书简报代笔")) return "brief";
  if (prompt.includes("开书顾问")) return "advisory";
  if (prompt.includes("人格策划") || prompt.includes("人格阵容")) return "persona";
  if (prompt.includes("人物分层") || prompt.includes("完整人物体系")) return "cast";
  if (prompt.includes("场景与实体设计师") || prompt.includes("场景库")) return "scenes";
  if (prompt.includes("总策划") || prompt.includes("只规划第")) return "structure";
  if (prompt.includes("小说正史记录员")) return "facts";
  if (prompt.includes("小说编辑审稿人")) return "review";
  if (prompt.includes("续写第")) return "prose";
  return "bible";
}

