// ─── 第 7 步：滚动策划 · 周期一（第 1–10 章）正稿 ─────────────────────────
// 卷一·禁航之海 首个批次：扬帆缔约 → 天枢闸 → 鲸落港聚齐初始船团 → 首枚残片。
// 第 11 章起未撰写的周期仍返回占位，启用前必须逐周期重写。

function refMapFromPrompt(prompt) {
  const map = new Map();
  for (const line of prompt.split("\n")) {
    const m = /^(E-[0-9A-Za-z]+)\s*\[(\w+)\]\s*([^\n：（]+?)(?:（[^）]*）)?：/.exec(line.trim());
    if (m) map.set(m[3].trim(), m[1]);
  }
  return map;
}

