function PLACEHOLDER_STRUCTURE(prompt, start, end) {
  return {
      volumes: [
        { title: `卷一·禁航之海（1-40章）`, outline: "扬帆、缔约、集齐初始船团，击退铁蝉。" },
        { title: "卷二·星骸深处（41-80章）", outline: "下潜古海遗迹，揭开第二次坠落真相。" },
        { title: "卷三·泊星之地（81-120章）", outline: "集齐残片抵达泊星港，完成泊与锚的抉择。" },
      ],
      cycle: {
        goal: "占位：启用前由主笔重写本周期正稿",
        openingState: "占位",
        climax: "占位",
        expectedClosingState: "占位",
      },
      chapters: Array.from({ length: end - start + 1 }, (_, index) => ({
        position: start + index,
        volumeTitle: "卷一·禁航之海",
        title: `第${start + index}章（占位，待主笔定稿）`,
        outline: "占位：启用第 7 步前必须替换为正稿章纲。",
        viewpoint: "岑野舟",
        characters: ["岑野舟", "阿泊"],
        scenes: ["锈锚坞", "星骸带"],
        items: ["起锚"],
        skills: [],
      })),
      proposals: [],
  };
}

function sse(res, text) {
  res.writeHead(200, {
    "content-type": "text/event-stream",
    "cache-control": "no-cache",
    "access-control-allow-origin": "*",
  });
  const chars = [...text];
  let index = 0;
  const timer = setInterval(() => {
    if (index < chars.length) {
      const delta = chars.slice(index, index + 6).join("");
      index += 6;
      res.write(`data: ${JSON.stringify({ choices: [{ delta: { content: delta } }] })}\n\n`);
    } else {
      res.write(`data: ${JSON.stringify({ choices: [{ delta: {} }], usage: { prompt_tokens: 100, completion_tokens: 100 } })}\n\n`);
      res.write("data: [DONE]\n\n");
      clearInterval(timer);
      res.end();
    }
  }, 40);
}

const server = createServer((req, res) => {
  const cors = {
    "access-control-allow-origin": req.headers.origin ?? "*",
    "access-control-allow-methods": "POST, OPTIONS",
    "access-control-allow-headers": "authorization, content-type",
  };
  if (req.method === "OPTIONS") {
    res.writeHead(204, cors);
    return res.end();
  }
  if (!req.url?.includes("/chat/completions")) {
    res.writeHead(404, cors);
    return res.end();
  }
  let body = "";
  req.on("data", (chunk) => (body += chunk));
  req.on("end", () => {
    const payload = JSON.parse(body || "{}");
    const prompt = payload.messages?.[0]?.content ?? "";
    const phase = phaseOf(prompt);
    if (payload.stream) {
      if (phase === "prose") {
        const m = /第(\d+)章/.exec(prompt);
        const num = m ? Number(m[1]) : 0;
        const text = CHAPTER_PROSE[num] ?? `【占位】第${num}章正文尚未由主笔撰写。`;
        return sse(res, text);
      }
      const text = phase === "style" ? JSON.stringify(STYLE_ANALYSIS) : PROSE_FALLBACK;
      return sse(res, text);
    }
    const response = RESPONSES[phase]
      ? RESPONSES[phase](prompt)
      : phase === "prose"
        ? (CHAPTER_EXTRA[Number((/第(\d+)章/.exec(prompt) || [])[1] || 0)] ?? "")
        : { error: `未实现的阶段: ${phase}` };
    setTimeout(() => {
      res.writeHead(200, { "content-type": "application/json", ...cors });
      res.end(
        JSON.stringify({
          choices: [{ message: { content: JSON.stringify(response) } }],
          usage: { prompt_tokens: 0, completion_tokens: 0 },
        }),
      );
    }, 400);
  });
});

const port = Number(process.env.AMY_AUTHOR_PORT || 8990);
server.listen(port, () => console.log(`author model on http://127.0.0.1:${port}/v1`));
